        if remote_ids := author.get('remote_ids'):
            existing_ids = dict(existing.get('remote_ids') or {})
            merged_ids, _matching_ids = existing.merge_remote_ids(remote_ids)
            if merged_ids != existing_ids:
                existing['remote_ids'] = merged_ids
                modified = True
        if modified:
            # Thing stores model data in its private mapping, so this marker is
            # transient and lets build_author_reply save only changed matches.
            existing._author_import_modified = True
        return existing
    a = {'type': {'key': '/type/author'}}
    for f in 'name', 'title', 'personal_name', 'birth_date', 'death_date', 'date':
        if f in author:
            a[f] = author[f]
    if remote_ids := author.get('remote_ids'):
        a['remote_ids'] = dict(remote_ids)
    return a


